    const base = g.createLinearGradient(0, H, 0, H - 1.1 * sy); base.addColorStop(0, 'rgba(25,22,18,0.55)'); base.addColorStop(1, 'rgba(25,22,18,0)'); g.fillStyle = base; g.fillRect(0, H - 1.1 * sy, W, 1.1 * sy);
