    const pal = [['#d84a6a', '#f2c03a'], ['#3aa3e0', '#6a3fd8'], ['#e8e8e8', '#7a7a7a'], ['#46c47a', '#1b6e7c'], ['#f07a2a', '#f5df5a']][Math.floor(R() * 5)];
