    const shop = new T.Mesh(new T.BoxGeometry(w + 0.02, 3.2, d + 0.02), K.verre); shop.position.y = 1.6; g.add(shop);
    const band = new T.Mesh(new T.BoxGeometry(w + 0.1, 0.5, d + 0.1), K.betonClair); band.position.y = 3.45; g.add(band);
