    for (let k = 0; k < 40; k++) { const x = R() * N, L = 40 + R() * 200; const gr = g.createLinearGradient(0, 0, 0, L); gr.addColorStop(0, 'rgba(40,30,25,0.18)'); gr.addColorStop(1, 'rgba(40,30,25,0)'); g.fillStyle = gr; g.fillRect(x, 0, 3 + R() * 8, L); }
