    g.strokeStyle = 'rgba(170,176,180,1)'; g.lineWidth = 3; for (let k = -N; k < 2 * N; k += 32) { g.beginPath(); g.moveTo(k, 0); g.lineTo(k + N, N); g.stroke(); g.beginPath(); g.moveTo(k + N, 0); g.lineTo(k, N); g.stroke(); }
