    bx(g, 0.02, 0.18, 0.3, std('ecranMonnayeur', 0x0b1418, 0.2, 0, { emissive: 0x2d8a6a, emissiveIntensity: 0.7 }), o.w / 2 + 0.01, H / 2 - 0.3, 0);
    const neck = cyl(g, 0.04, 1.3, std('inox', 0xb8bcc0, 0.25, 0.9), 0, H / 2 + 0.65, 0, 8);
