    if (v && u && this.alliesOf(u).some(a => a.alive && (Math.hypot(a.x - v.x, a.z - v.z) < 1.3 || (a.peek && Math.hypot(a.peek.px - v.x, a.peek.pz - v.z) < 1.3)))) return null;
