      g += `<line x1="5" y1="${y}" x2="37" y2="${y}" stroke="${on ? '#6fe3a0' : 'currentColor'}" stroke-opacity="${on ? 1 : 0.35}" stroke-width="${on ? 3.4 : 2.4}" stroke-linecap="round"/>`;
