    const arg = { x: Math.round(p.x * 100) / 100, z: Math.round(p.z * 100) / 100, units: ids };
    if (top) { topAdd('lampadaire', arg, `éteindre le lampadaire (${ordWhoIds(ids)})`, p); return; }
    const r = battle.command('lampadaire', 0, arg);
